function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // character
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();

  // body
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 100);
  ctx.stroke();

  // arms
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 - 30, H/2 + 70);
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 + 30, H/2 + 70);
  ctx.stroke();

  // legs
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 100);
  ctx.lineTo(W/2 - 20 + 10 * Math.sin(t), H/2 + 150);
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 100);
  ctx.lineTo(W/2 + 20 - 10 * Math.sin(t), H/2 + 150);
  ctx.stroke();

  // event element: door
  ctx.fillStyle = 'black';
  ctx.fillRect(W/2 - 50, H/2 + 150, 100, 20);

  // event element: door opening
  ctx.fillStyle = 'white';
  ctx.fillRect(W/2 - 50 + 50 * Math.sin(t), H/2 + 150, 50, 20);

  ctx.restore();
}
